package org.mockito.internal.verification;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.exceptions.base.MockitoAssertionError;
import org.mockito.exceptions.verification.junit.ArgumentsAreDifferent;
import org.mockito.internal.util.Timer;
import org.mockito.internal.verification.MockitoAssertionError;
import org.mockito.internal.verification.VerificationData;
import org.mockito.internal.verification.VerificationMode;
import org.mockito.internal.verification.api.VerificationData;
import org.mockito.verification.VerificationMode;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class VerificationOverTimeImpl_verify_TriageGen1Test {

    private VerificationMode delegate;
    private Timer timer;
    private VerificationData data;

    @Before
    public void setUp() {
        delegate = mock(VerificationMode.class);
        timer = mock(Timer.class);
        data = mock(VerificationData.class);
    }

    @Test
    public void testVerify_SuccessWithReturnOnSuccessTrue() {
        // Setup: Timer runs once, delegate succeeds, returnOnSuccess is true
        when(timer.isCounting()).thenReturn(true, false);

        VerificationOverTimeImpl impl = new VerificationOverTimeImpl(10, 100, delegate, true, timer);

        impl.verify(data);

        verify(delegate).verify(data);
        verify(timer).start();
    }

    @Test
    public void testVerify_SuccessWithReturnOnSuccessFalse_EventuallySucceeds() {
        // Setup: Timer runs twice. First attempt fails, second succeeds. returnOnSuccess is false.
        when(timer.isCounting()).thenReturn(true, true, false);
        doThrow(new MockitoAssertionError("fail")).doNothing().when(delegate).verify(data);

        // We need to mock handleVerifyException. Since it's a protected method in the same class, 
        // and we are testing the real implementation, we assume it returns the error.
        // However, since we can't easily mock the internal 'handleVerifyException' without a spy,
        // we test the flow where error becomes null on success.

        VerificationOverTimeImpl impl = spy(new VerificationOverTimeImpl(10, 100, delegate, false, timer));
        doReturn(new MockitoAssertionError("fail")).when(impl).handleVerifyException(any());

        impl.verify(data);

        verify(delegate, times(2)).verify(data);
    }

    @Test
    public void testVerify_ThrowsError_MockitoAssertionError() {
        // Setup: Timer runs once, delegate throws MockitoAssertionError
        when(timer.isCounting()).thenReturn(true, false);
        doThrow(new MockitoAssertionError("assertion error")).when(delegate).verify(data);

        VerificationOverTimeImpl impl = spy(new VerificationOverTimeImpl(10, 100, delegate, true, timer));
        MockitoAssertionError expectedError = new MockitoAssertionError("handled error");
        doReturn(expectedError).when(impl).handleVerifyException(any());

        try {
            impl.verify(data);
            fail("Expected assertion error to be thrown");
        } catch (AssertionError e) {
            assertEquals(expectedError, e);
        }
    }

    @Test
    public void testVerify_ThrowsError_ArgumentsAreDifferent() {
        // Setup: Timer runs once, delegate throws ArgumentsAreDifferent
        when(timer.isCounting()).thenReturn(true, false);
        doThrow(mock(ArgumentsAreDifferent.class)).when(delegate).verify(data);

        VerificationOverTimeImpl impl = spy(new VerificationOverTimeImpl(10, 100, delegate, true, timer));
        ArgumentsAreDifferent expectedError = mock(ArgumentsAreDifferent.class);
        doReturn(expectedError).when(impl).handleVerifyException(any());

        try {
            impl.verify(data);
            fail("Expected assertion error to be thrown");
        } catch (AssertionError e) {
            assertEquals(expectedError, e);
        }
    }

    @Test
    public void testVerify_FailureUntilTimerEnds() {
        // Setup: Timer runs twice, both fail, returnOnSuccess is false.
        // Last error should be thrown.
        when(timer.isCounting()).thenReturn(true, true, false);
        doThrow(new MockitoAssertionError("fail")).when(delegate).verify(data);

        VerificationOverTimeImpl impl = spy(new VerificationOverTimeImpl(10, 100, delegate, false, timer));
        MockitoAssertionError error1 = new MockitoAssertionError("error 1");
        MockitoAssertionError error2 = new MockitoAssertionError("error 2");

        doReturn(error1).doReturn(error2).when(impl).handleVerifyException(any());

        try {
            impl.verify(data);
            fail("Expected error to be thrown");
        } catch (AssertionError e) {
            assertEquals(error2, e);
        }
    }

    @Test
    public void testVerify_TimerNeverCounts() {
        // Setup: Timer is not counting from the start
        when(timer.isCounting()).thenReturn(false);

        VerificationOverTimeImpl impl = new VerificationOverTimeImpl(10, 100, delegate, true, timer);

        impl.verify(data);

        verify(delegate, never()).verify(data);
    }
}
